    out = [row[:] for row in grid]
    if not grid or not grid[0]:
        return out
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # Each motif occupies one or more consecutive rows containing non-background
    # cells. Match equal-height bands and use the lower band's rightward extension.
    active = [any(value != background for value in row) for row in grid]
    bands = []
    r = 0
    while r < h:
        if not active[r]:
            r += 1
            continue
        start = r
        while r < h and active[r]:
            r += 1
        bands.append((start, r))

    best = None
    best_score = 0
    for i, (a0, a1) in enumerate(bands):
        for b0, b1 in bands[i + 1:]:
            if a1 - a0 != b1 - b0:
                continue
            additions = []
            for k in range(a1 - a0):
                upper, lower = grid[a0 + k], grid[b0 + k]
                upper_fg = [c for c, v in enumerate(upper) if v != background]
                lower_fg = [c for c, v in enumerate(lower) if v != background]
                if not upper_fg or not lower_fg:
                    continue
                upper_right = max(upper_fg)
                lower_right = max(lower_fg)
                if lower_right > upper_right:
                    for c in range(upper_right + 1, lower_right + 1):
                        if upper[c] == background and lower[c] != background:
                            additions.append((a0 + k, c))
            if len(additions) > best_score:
                best_score = len(additions)
                best = additions
    if best:
        for r, c in best:
            out[r][c] = 1
    return out


